      staffOptions: { page: 1, itemsPerPage: 10 },
      staffFilter: { name: "", position: "" },
      staffDebounce: null,
      staffHeaders: [
        { text: "Name", value: "name", sortable: false },
        { text: "Position", value: "position", sortable: false },
        { text: "Facility", value: "facility", sortable: false },
        {
          text: "",
          value: "_action",
          sortable: false,
          align: "center",
          width: 100,
        },
      ],

      // ── Destination position picker ────────────────────────────────
      positionDialog: false,
      positionItems: [],
      positionTotal: 0,
      loadingPositions: false,
      positionOptions: { page: 1, itemsPerPage: 10 },
      posFilter: { designation: "" },
      posDebounce: null,
      positionHeaders: [
        { text: "Designation", value: "designation", sortable: false },
        { text: "Department", value: "department", sortable: false },
        { text: "Facility", value: "facility", sortable: false },
        { text: "Grade", value: "grade", sortable: false },
        { text: "Vacant / Max", value: "vacant", sortable: false, width: 130 },
        {
          text: "",
          value: "_action",
          sortable: false,
          align: "center",
          width: 100,
        },
      ],

      rules: {
        required: (v) => !!v || "This field is required",
        minLeadTime: (v) =>
          !v ||
          v >= this.minTransferDate ||
          `Must be on or after ${this.minTransferDate} (3 months' notice)`,
      },

      snackbar: { show: false, text: "", color: "success" },
    };
  },

  computed: {
    minTransferDate() {
      const d = new Date();
      d.setMonth(d.getMonth() + 3);
      return d.toISOString().substr(0, 10);
    },

    positionsMatch() {
      return (
        !!this.form.currentPosition.reference &&
        !!this.form.destinationPosition.reference &&
        this.form.currentPosition.reference ===
          this.form.destinationPosition.reference
      );
    },

    designationMismatch() {
      return (
        !!this.form.currentPosition.display &&
        !!this.form.destinationPosition.display &&
        this.form.currentPosition.display !==
          this.form.destinationPosition.display
      );
    },
  },

  watch: {
    staffOptions: {
      handler() {
        if (this.staffDialog) this.fetchStaff();
      },
      deep: true,
    },
    positionOptions: {
      handler() {
        if (this.positionDialog) this.fetchPositions();
      },
      deep: true,
    },
  },

  async mounted() {
    await this.checkAccess();
  },

  methods: {
    async checkAccess() {
      try {
        // Wait for generalMixin to finish loading loggedInStaff
        await new Promise((resolve) => {
          if (!this.loadingUserData) {
            resolve();
            return;
          }
          const unwatch = this.$watch("loadingUserData", (newValue) => {
            if (!newValue) {
              unwatch();
              resolve();
            }
          });
          setTimeout(() => {
            unwatch();
            resolve();
          }, 15000);
        });

        const practitionerId =
          this.loggedInStaff && this.loggedInStaff.practitioner;
        if (!practitionerId) {
          this.accessChecked = true;
          return;
        }

        const resp = await fetch(
          "/site/general/getDepartmentalDirector/" + practitionerId,
        );
        if (!resp.ok) throw new Error("HTTP " + resp.status);
        const directors = await resp.json();

        this.isDirector = Array.isArray(directors)
          ? directors.some((d) => d.practitioner === practitionerId)
          : false;
      } catch (err) {
        console.error("checkAccess error:", err);
        this.isDirector = false;
      } finally {
        this.accessChecked = true;
      }
    },

    scrollTo(section) {
      const el = document.getElementById("section-" + section);
      if (el) el.scrollIntoView({ behavior: "smooth" });
    },

    goBack() {
      this.$router.go(-1);
    },

    getInitials(name) {
      if (!name) return "?";
      return name
        .split(" ")
        .filter(Boolean)
        .slice(0, 2)
        .map((n) => n[0].toUpperCase())
        .join("");
    },

    showSnackbar(text, color) {
      this.snackbar = { show: true, text, color: color || "success" };
    },

    // ── Staff picker ──────────────────────────────────────────────────
    debouncedFetchStaff() {
      clearTimeout(this.staffDebounce);
      this.staffDebounce = setTimeout(() => {
        this.staffOptions.page = 1;
        this.fetchStaff();
      }, 350);
    },

    async fetchStaff() {
      this.loadingStaff = true;
      try {
        const params = new URLSearchParams({
          page: this.staffOptions.page,
          count: this.staffOptions.itemsPerPage,
        });
        if (this.staffFilter.name) params.set("name", this.staffFilter.name);
        if (this.staffFilter.position)
          params.set("position", this.staffFilter.position);
        // Locked to the logged-in Departmental Director's own department —
        // directors may only recommend transfers for staff within their
        // own department.
        const deptCode = this.loggedInStaff?.department?.code;
        if (deptCode) params.set("department", deptCode);

        const res = await fetch(`/site/position/supervisors?${params}`);
        const data = await res.json();

        this.staffTotal = data.total || 0;
        this.staffItems = data.supervisors || [];
      } catch (err) {
        console.error("fetchStaff error", err);
      } finally {
        this.loadingStaff = false;
      }
    },

    selectStaff(item) {
      this.form.staff = {
        reference: item.practitionerRef,
        display: item.name,
        position: item.position,
        facility: item.facility,
      };
      this.form.currentPosition = {
        reference: item.positionRef,
        display: item.position,
        facility: item.facility,
        department: item.department,
      };
      this.staffDialog = false;
    },

    clearStaff() {
      this.form.staff = {
        reference: null,
        display: "",
        position: "",
        facility: "",
      };
      this.form.currentPosition = {
        reference: null,
        display: "",
        facility: "",
        department: "",
      };
    },

    // ── Destination position picker ─────────────────────────────────
    debouncedFetchPositions() {
      clearTimeout(this.posDebounce);
      this.posDebounce = setTimeout(() => {
        this.positionOptions.page = 1;
        this.fetchPositions();
      }, 350);
    },

    async fetchPositions() {
      this.loadingPositions = true;
      try {
        const params = new URLSearchParams({
          page: this.positionOptions.page,
          count: this.positionOptions.itemsPerPage,
        });
        if (this.posFilter.designation)
          params.set("designation", this.posFilter.designation);
        // Locked to the logged-in Departmental Director's own department —
        // directors may only transfer staff into positions within their
        // own department.
        const deptCode = this.loggedInStaff?.department?.code;
        if (deptCode) params.set("department", deptCode);

        const res = await fetch(`/site/position/report?${params}`);
        const data = await res.json();

        this.positionTotal = data.total || 0;
        this.positionItems = data.positions || [];
      } catch (err) {
        console.error("fetchPositions error", err);
      } finally {
        this.loadingPositions = false;
      }
    },

    isSelectablePosition(item) {
      return (
        item.vacant > 0 &&
        item.reference !== this.form.currentPosition.reference
      );
    },

    positionSelectHint(item) {
      if (item.reference === this.form.currentPosition.reference) {
        return "This is the staff member's current position";
      }
      if (item.vacant <= 0) return "No vacant posts available";
      return "Select this position";
    },

    selectDestinationPosition(item) {
      if (!this.isSelectablePosition(item)) return;
      this.form.destinationPosition = {
        reference: item.reference,
        display: item.designation,
        facility: item.facility,
        department: item.department,
        grade: item.grade,
        vacant: item.vacant,
        maxPosts: item.maxPosts,
      };
      this.positionDialog = false;
    },

    clearDestinationPosition() {
      this.form.destinationPosition = {
        reference: null,
        display: "",
        facility: "",
        department: "",
        grade: "",
        vacant: 0,
        maxPosts: 0,
      };
    },

    async submitForm() {
      this.formSubmitted = true;
      const valid = this.$refs.form.validate();
      if (
        !valid ||
        !this.form.staff.reference ||
        !this.form.destinationPosition.reference
      ) {
        this.showSnackbar("Please complete all required fields.", "error");
        return;
      }
      if (this.positionsMatch) {
        this.showSnackbar(
          "Destination position must be different from the current position.",
          "error",
        );
        return;
      }
      if (this.designationMismatch) {
        this.showSnackbar(
          "A transfer must retain the staff member's designation. Choose a destination position with a matching designation.",
          "error",
        );
        return;
      }

      this.saving = true;
      try {
        this.fhir = {
          practitioner: this.form.staff.reference,
          currentPosition: this.form.currentPosition.reference,
          destinationPosition: this.form.destinationPosition.reference,
          plannedTransferDate: this.form.plannedTransferDate,
          transferReason: this.form.transferReason,
        };
        this.afterSaveMessage =
          "Transfer recommendation submitted successfully!";
        await this.processFHIR();
        this.showSnackbar(this.afterSaveMessage, "success");
        setTimeout(() => this.goBack(), 200);
      } catch (err) {
        console.error("submitForm error:", err);
        this.showSnackbar(
          "Failed to submit recommendation. Please try again.",
          "error",
        );
      } finally {
        this.saving = false;
      }
    },
  },
};
</script>

